@router.delete("/me", status_code=204)
def delete_me(user: dict = Depends(get_current_user)):
    """현재 로그인한 계정을 영구 삭제합니다."""
    deleted = get_repository().delete_user(user["id"])
    if not deleted:
        raise HTTPException(status_code=404, detail="User not found.")
